    private void delayed(TrackingService.Snapshot s){rendered="DELAYED";startRequested=false;LinearLayout body=Design.darkPage(this);Design.pad(body,24,24);Design.space(body,30);text(body,"Starting after a delay",27,600,Design.CREAM).setGravity(Gravity.CENTER);Design.space(body,24);elapsed=text(body,duration(s.delayRemaining),48,700,Design.LILAC);elapsed.setGravity(Gravity.CENTER);Design.space(body,18);text(body,"No sensors or audio are recording",16,500,Design.CREAM).setGravity(Gravity.CENTER);reserveInfo=text(body,s.reserveStatus,13,500,Design.LILAC);reserveInfo.setGravity(Gravity.CENTER);Design.space(body,14);text(body,s.sonar?"Contactless speaker and microphone capture remain stopped.":s.soundsRequested?"Your selected sound analysis begins only when recording starts.":"Microphone capture remains off.",14,400,Design.LILAC);Design.space(body,20);text(body,"Waiting time is excluded from the saved recording. Keep the phone in place.",13,400,Design.LILAC);LinearLayout buttons=footer(body);action(buttons,"Start recording now",true,()->delayCommand(TrackingService.DELAY_NOW));action(buttons,"Cancel delayed start",false,()->delayCommand(TrackingService.STOP));}
    private void delayCommand(String action){TrackingService.Snapshot s=runtime.snapshot();if(s==null||!s.phase.equals("DELAYED"))return;try{runtime.command(this,new Intent(this,TrackingService.class).setAction(action).putExtra("delayOwner",s.delayOwner));}catch(RuntimeException failure){Ui.toast(this,"Could not change delayed start: "+failure.getMessage());}}
