    private void updateArmed(TrackingService.Snapshot s){if(reserveInfo!=null)reserveInfo.setText(s.reserveStatus);subtitle.setText(s.automaticState.equals("WAITING_CHARGING")?"Waiting for charging":s.automaticState.equals("WAITING_SCREEN_OFF")?"Waiting for the screen to turn off":s.automaticState.equals("WAIT_CONDITIONS_UNAVAILABLE")?"Wait conditions could not be read. Cancel and try again.":s.automaticState.equals("SCREEN_IN_USE")?"Waiting for the screen to turn off":(s.automaticState.equals("QUIET")||s.automaticState.equals("START"))?"Still for "+duration(s.quietMillis)+" / 15 min":s.automaticState.equals("COLLECTING")?"Waiting for a continuous movement signal":"Waiting for your selected start time");if(!s.googleSignal.isEmpty())subtitle.append("\n\n"+s.googleSignal);}
    private void refresh(){TrackingService.Snapshot s=runtime.snapshot();if(s!=null){if(s.phase.equals("DELAYED")){if(!rendered.equals("DELAYED"))delayed(s);else{elapsed.setText(duration(s.delayRemaining));if(reserveInfo!=null)reserveInfo.setText(s.reserveStatus);}return;}if(s.phase.equals("ARMED")){if(!rendered.equals("ARMED"))armed(s);else updateArmed(s);return;}if(!rendered.equals(s.phase))live(s);else if(!rendered.equals("SETUP"))update(s);return;}if(rendered.equals("DELAYED")){TrackingDelayRuntime.State saved=TrackingDelayRuntime.get(this).state;setupIssue=Prefs.text(this,"trackingError","");if(setupIssue.isEmpty())setupIssue=saved.plan!=null&&!saved.plan.pending()?saved.plan.status():"Waiting ended. Review delayed-start status.";setup();return;}if(rendered.equals("ARMED")){setup();return;}if(sawLive){if(finishingFlow)return;finishingFlow=true;String failure=Prefs.text(this,"trackingError","");if(failure.isEmpty())finishRecording();else new AlertDialog.Builder(this).setTitle("Recording needs attention").setMessage(failure).setPositiveButton("View records",(d,w)->finishRecording()).setCancelable(false).show();}else if(startRequested){startRequested=false;primary.setEnabled(true);primary.setText("Start tracking  →");showError(Prefs.text(this,"trackingError","Tracking did not start. Try again."));}else if(getIntent().getBooleanExtra("automaticRequest",false)){String failure=Prefs.text(this,"trackingError","");if(!failure.isEmpty())showError(failure);}}
    private void finishRecording(){setResult(RESULT_OK);runtime.review(this);}
    private void reviewDefault(){setResult(RESULT_OK);if(isTaskRoot())startActivity(new Intent(this,MainActivity.class).putExtra("showReport",true));finish();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused){Design.focusedSystemBars(this,true);if(resumed&&resumeAfterFocus){resumeAfterFocus=false;command(TrackingService.RESUME);}}}
